import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Dialog } from 'radix-ui'
import { Copy, Download, Laptop, Plus, ShieldOff, Trash2, X } from 'lucide-react'

import { orpc } from '#/orpc/client'
import { m } from '#/paraglide/messages'
import { CustomerCombobox } from './customer-combobox'
import { useToast } from './toast'

type Platform = 'windows' | 'linux' | 'macos'

type CreatedEnrollment = {
  id: string
  kind: 'single' | 'permanent'
  rustdeskVersion: string
  scripts: Record<Platform, string>
}

const PLATFORMS: Array<{ id: Platform; label: string; extension: string }> = [
  { id: 'windows', label: 'Windows', extension: 'ps1' },
  { id: 'linux', label: 'Linux', extension: 'sh' },
  { id: 'macos', label: 'macOS', extension: 'sh' },
]

export function EnrollmentDialog({
  open,
  onOpenChange,
  customerNames,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  customerNames: string[]
}) {
  const queryClient = useQueryClient()
  const { toast } = useToast()
  const [name, setName] = useState('')
  const [kind, setKind] = useState<'single' | 'permanent'>('single')
  const [installIfMissing, setInstallIfMissing] = useState(true)
  const [customer, setCustomer] = useState('')
  const [tags, setTags] = useState('')
  const [rustdeskConfig, setRustdeskConfig] = useState('')
  const [created, setCreated] = useState<CreatedEnrollment | null>(null)
  const [scriptSaved, setScriptSaved] = useState(false)
  const [platform, setPlatform] = useState<Platform>('windows')

  const listQuery = useQuery(
    orpc.enrollments.list.queryOptions({ input: {}, enabled: open }),
  )
  const invalidate = () =>
    queryClient.invalidateQueries({ queryKey: orpc.enrollments.key() })

  const createMut = useMutation(
    orpc.enrollments.create.mutationOptions({
      onSuccess: (result) => {
        setCreated(result)
        setScriptSaved(false)
        setPlatform('windows')
        setName('')
        invalidate()
        toast(m.enrollment_created())
      },
      onError: (error) => toast(error.message),
    }),
  )
  const scriptsMut = useMutation(
    orpc.enrollments.scripts.mutationOptions({
      onSuccess: (result) => {
        setCreated(result)
        setScriptSaved(false)
        setPlatform('windows')
        if (result.rotated) toast(m.enrollment_token_rotated())
      },
      onError: (error) => toast(error.message),
    }),
  )
  const revokeMut = useMutation(
    orpc.enrollments.revoke.mutationOptions({
      onSuccess: () => {
        invalidate()
        toast(m.enrollment_revoked())
      },
      onError: (error) => toast(error.message),
    }),
  )
  const removeMut = useMutation(
    orpc.enrollments.remove.mutationOptions({
      onSuccess: () => {
        invalidate()
        toast(m.enrollment_deleted())
      },
      onError: (error) => toast(error.message),
    }),
  )

  function createToken() {
    createMut.mutate({
      name: name.trim(),
      kind,
      installIfMissing,
      customer: customer.trim(),
      tags: tags
        .split(',')
        .map((tag) => tag.trim())
        .filter(Boolean),
      rustdeskConfig: rustdeskConfig.trim(),
      baseUrl: window.location.origin,
    })
  }

  async function copyScript() {
    if (!created) return
    try {
      await navigator.clipboard.writeText(created.scripts[platform])
      setScriptSaved(true)
      toast(m.enrollment_script_copied())
    } catch {
      toast(m.enrollment_copy_failed())
    }
  }

  function downloadScript() {
    if (!created) return
    const meta = PLATFORMS.find((item) => item.id === platform)!
    const blob = new Blob([created.scripts[platform]], { type: 'text/plain' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `rustdesk-book-deploy-${platform}.${meta.extension}`
    link.click()
    setScriptSaved(true)
    setTimeout(() => URL.revokeObjectURL(link.href), 1000)
  }

  const currentScript = created?.scripts[platform] ?? ''

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (
          !next &&
          created?.kind === 'single' &&
          !scriptSaved &&
          !window.confirm(m.enrollment_close_warning())
        ) {
          return
        }
        onOpenChange(next)
        if (!next) setCreated(null)
      }}
    >
      <Dialog.Portal>
        <Dialog.Overlay className="tv-dialog-overlay" />
        <Dialog.Content className="tv-dialog" style={{ maxWidth: 760, maxHeight: '90vh' }}>
          <div className="tv-dialog__header">
            <Dialog.Title className="tv-dialog__title">
              {m.enrollment_title()}
            </Dialog.Title>
            <Dialog.Description className="tv-dialog__description">
              {m.enrollment_description()}
            </Dialog.Description>
          </div>

          {created ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12, minHeight: 0 }}>
              <div
                style={{
                  padding: '10px 12px',
                  borderRadius: 6,
                  border: '1px solid var(--s-warn)',
                  background: 'color-mix(in srgb, var(--s-warn) 10%, transparent)',
                  fontSize: 12,
                }}
              >
                <strong>
                  {created.kind === 'permanent'
                    ? m.enrollment_token_permanent_title()
                    : m.enrollment_token_once_title()}
                </strong>{' '}
                {created.kind === 'permanent'
                  ? m.enrollment_token_permanent_hint()
                  : m.enrollment_token_once_hint()}
              </div>

              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                {PLATFORMS.map((item) => (
                  <button
                    key={item.id}
                    className={`tv-btn tv-btn--sm ${platform === item.id ? 'tv-btn--default' : 'tv-btn--ghost'}`}
                    onClick={() => setPlatform(item.id)}
                  >
                    {item.label}
                  </button>
                ))}
                <span style={{ flex: 1 }} />
                <button className="tv-btn tv-btn--ghost tv-btn--sm" onClick={copyScript}>
                  <Copy size={13} /> {m.enrollment_copy_script()}
                </button>
                <button className="tv-btn tv-btn--ghost tv-btn--sm" onClick={downloadScript}>
                  <Download size={13} /> {m.enrollment_download_script()}
                </button>
              </div>

              <textarea
                className="tv-input"
                readOnly
                value={currentScript}
                aria-label={m.enrollment_script_label()}
                style={{
                  minHeight: 300,
                  resize: 'vertical',
                  fontFamily: 'var(--font-mono, monospace)',
                  fontSize: 11,
                  lineHeight: 1.45,
                  whiteSpace: 'pre',
                }}
              />
              <div style={{ fontSize: 11.5, color: 'var(--fg-4)' }}>
                {platform === 'windows'
                  ? m.enrollment_run_windows()
                  : m.enrollment_run_unix()}
              </div>
              <button className="tv-btn tv-btn--default tv-btn--sm" onClick={() => setCreated(null)}>
                <Plus size={13} /> {m.enrollment_create_another()}
              </button>
            </div>
          ) : (
            <>
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: 10,
                }}
              >
                <div className="tv-field">
                  <label className="tv-label" htmlFor="enrollment-name">
                    {m.enrollment_name()}
                  </label>
                  <input
                    id="enrollment-name"
                    className="tv-input"
                    value={name}
                    onChange={(event) => setName(event.target.value)}
                    placeholder={m.enrollment_name_placeholder()}
                  />
                </div>
                <div className="tv-field">
                  <label className="tv-label" htmlFor="enrollment-kind">
                    {m.enrollment_type()}
                  </label>
                  <select
                    id="enrollment-kind"
                    className="tv-select"
                    value={kind}
                    onChange={(event) => setKind(event.target.value as typeof kind)}
                  >
                    <option value="single">{m.enrollment_type_single()}</option>
                    <option value="permanent">{m.enrollment_type_permanent()}</option>
                  </select>
                </div>
                <div className="tv-field">
                  <label className="tv-label" htmlFor="enrollment-customer">
                    {m.form_customer_label()}
                  </label>
                  <CustomerCombobox
                    id="enrollment-customer"
                    value={customer}
                    onChange={setCustomer}
                    options={customerNames}
                    placeholder={m.form_customer_ph()}
                    commitMode="change"
                    allowCreate
                    aria-label={m.form_customer_label()}
                  />
                </div>
                <div className="tv-field">
                  <label className="tv-label" htmlFor="enrollment-tags">
                    {m.form_tags_label()}
                  </label>
                  <input
                    id="enrollment-tags"
                    className="tv-input"
                    value={tags}
                    onChange={(event) => setTags(event.target.value)}
                    placeholder={m.form_tags_ph()}
                  />
                </div>
                <div className="tv-field" style={{ gridColumn: '1 / -1' }}>
                  <label className="tv-label" htmlFor="enrollment-config">
                    {m.enrollment_config()}
                  </label>
                  <textarea
                    id="enrollment-config"
                    className="tv-input"
                    value={rustdeskConfig}
                    onChange={(event) => setRustdeskConfig(event.target.value)}
                    placeholder={m.enrollment_config_placeholder()}
                    style={{ minHeight: 62, resize: 'vertical' }}
                  />
                  <span style={{ fontSize: 11, color: 'var(--fg-4)' }}>
                    {m.enrollment_config_hint()}
                  </span>
                </div>
                <label
                  style={{
                    gridColumn: '1 / -1',
                    display: 'flex',
                    gap: 8,
                    alignItems: 'center',
                    cursor: 'pointer',
                  }}
                >
                  <input
                    type="checkbox"
                    checked={installIfMissing}
                    onChange={(event) => setInstallIfMissing(event.target.checked)}
                  />
                  <span>
                    <strong>{m.enrollment_install_missing()}</strong>
                    <span style={{ display: 'block', fontSize: 11, color: 'var(--fg-4)' }}>
                      {m.enrollment_install_missing_hint()}
                    </span>
                  </span>
                </label>
              </div>

              <button
                className="tv-btn tv-btn--default tv-btn--sm"
                disabled={!name.trim() || createMut.isPending}
                onClick={createToken}
                style={{ alignSelf: 'flex-start' }}
              >
                <Laptop size={14} /> {m.enrollment_create()}
              </button>

              <div style={{ borderTop: '1px solid var(--bd-1)', paddingTop: 12 }}>
                <div style={{ fontSize: 12, fontWeight: 600, marginBottom: 8 }}>
                  {m.enrollment_existing()}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {listQuery.data?.length === 0 && (
                    <span style={{ fontSize: 12, color: 'var(--fg-4)' }}>
                      {m.enrollment_none()}
                    </span>
                  )}
                  {listQuery.data?.map((token) => {
                    const inactive = Boolean(token.revokedAt) ||
                      (token.kind === 'single' && token.useCount > 0)
                    return (
                      <div
                        key={token.id}
                        style={{
                          display: 'flex',
                          gap: 10,
                          alignItems: 'center',
                          padding: '8px 10px',
                          border: '1px solid var(--bd-1)',
                          borderRadius: 6,
                          background: 'var(--bg-sunken)',
                          opacity: inactive ? 0.65 : 1,
                        }}
                      >
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ display: 'flex', gap: 7, alignItems: 'center' }}>
                            <strong style={{ fontSize: 12.5 }}>{token.name}</strong>
                            <span className="tv-chip">
                              {token.kind === 'single'
                                ? m.enrollment_type_single_short()
                                : m.enrollment_type_permanent_short()}
                            </span>
                          </div>
                          <div style={{ fontSize: 11, color: 'var(--fg-4)', marginTop: 2 }}>
                            {token.tokenPrefix} · {m.enrollment_uses({ count: token.useCount })}
                            {token.customer ? ` · ${token.customer}` : ''}
                            {inactive ? ` · ${m.enrollment_inactive()}` : ''}
                          </div>
                        </div>
                        {token.kind === 'permanent' && !token.revokedAt && (
                          <button
                            className="tv-btn tv-btn--ghost tv-btn--icon-xs"
                            title={m.enrollment_download_again()}
                            aria-label={m.enrollment_download_again()}
                            disabled={scriptsMut.isPending}
                            onClick={() =>
                              scriptsMut.mutate({
                                id: token.id,
                                baseUrl: window.location.origin,
                              })
                            }
                          >
                            <Download size={14} />
                          </button>
                        )}
                        {!token.revokedAt && (
                          <button
                            className="tv-btn tv-btn--ghost tv-btn--icon-xs"
                            title={m.enrollment_revoke()}
                            aria-label={m.enrollment_revoke()}
                            style={{ color: 'var(--s-err)' }}
                            onClick={() => revokeMut.mutate({ id: token.id })}
                          >
                            <ShieldOff size={14} />
                          </button>
                        )}
                        <button
                          className="tv-btn tv-btn--ghost tv-btn--icon-xs"
                          title={m.enrollment_delete()}
                          aria-label={m.enrollment_delete()}
                          style={{ color: 'var(--s-err)' }}
                          disabled={removeMut.isPending}
                          onClick={() => {
                            if (window.confirm(m.enrollment_delete_confirm({ name: token.name }))) {
                              removeMut.mutate({ id: token.id })
                            }
                          }}
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    )
                  })}
                </div>
              </div>
            </>
          )}

          <Dialog.Close asChild>
            <button
              className="tv-btn tv-btn--ghost tv-btn--icon-sm"
              aria-label={m.common_close()}
              style={{ position: 'absolute', top: 8, right: 8 }}
            >
              <X size={16} />
            </button>
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

text:
export const DEFAULT_RUSTDESK_VERSION = '1.4.9'

export type DeploymentPlatform = 'windows' | 'linux' | 'macos'

export interface DeploymentScriptOptions {
  baseUrl: string
  token: string
  installIfMissing: boolean
  rustdeskConfig?: string | null
}

const DOWNLOAD_SHA256 = {
  windows: {
    x86_64: 'c87d2f4cef2a5acd6003b6507dcfbf5d5168a256db082cd90b54d35193224aaa',
    aarch64: '30bc8925e62c7ade52371758c2b944036ed2386f6c554e9e59f3bcfef06c7cd9',
  },
  deb: {
    x86_64: '7244ba47c40e804172044bfbe659467c54ce46554c98e78c8c0406f1d612fda3',
    aarch64: 'ce62c996f14d33f3bbe3a330e953644a44bace7f05885a7953f7395d69fb49c0',
  },
  rpm: {
    x86_64: 'eb1b053ac5b2f774f2271f7fbbfd2ea475899f7a55135c5e172bc54b9388f108',
    aarch64: '3e523df7ceb6f3804b047a3cac797354c4bf46ec19f2d7ff5e198787003cb092',
  },
  suse: {
    x86_64: 'b28bdb5a4afcd3f0475664ad2e635eb4209f15ed44566f83469453b175e8a197',
    aarch64: 'e426192be57357eb9178f886b92188d6839eeb438d64a206fcea9dfb49eaee59',
  },
  arch: '679760e1a1f1b930529069edfaec219afa16b5efe44c1bc593cede0e65576c11',
  macos: {
    x86_64: 'fa1129a0635019f9c5841937942cc2b08be028a192f47c009edde7e53812904e',
    aarch64: 'f7935597b247d42c8f2a2ed71176a9f5868018cd9e1a33b8096418a668c8caf0',
  },
} as const

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'"'"'`)}'`
}

function powershellQuote(value: string): string {
  return `'${value.replaceAll("'", "''")}'`
}

function normalizedOrigin(value: string): string {
  return new URL(value).origin
}

function windowsScript(options: DeploymentScriptOptions): string {
  const origin = normalizedOrigin(options.baseUrl)
  const version = DEFAULT_RUSTDESK_VERSION
  const config = options.rustdeskConfig?.trim() ?? ''
  const windowsHashes = DOWNLOAD_SHA256.windows

  return String.raw`# rustdesk-book deployment for Windows (RustDesk OSS)
# Run in an elevated PowerShell or as SYSTEM (GPO/Intune/RMM).
# This file contains a bearer token. Restrict access and delete it when no longer needed.
$ErrorActionPreference = 'Stop'
$ClaimUrl = ${powershellQuote(`${origin}/api/enroll/claim`)}
$FinalizeUrl = ${powershellQuote(`${origin}/api/enroll/finalize`)}
$EnrollmentToken = ${powershellQuote(options.token)}
$InstallIfMissing = $${options.installIfMissing ? 'true' : 'false'}
$RustDeskVersion = ${powershellQuote(version)}
$RustDeskConfig = ${powershellQuote(config)}

$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = [Security.Principal.WindowsPrincipal]::new($identity)
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
  throw 'Run this deployment as Administrator or SYSTEM.'
}

function Find-RustDesk {
  $service = Get-CimInstance Win32_Service -Filter "Name='RustDesk'" -ErrorAction SilentlyContinue
  if ($service -and $service.PathName) {
    $servicePath = [regex]::Match($service.PathName, '^(?:"([^"]+)"|([^ ]+))').Groups
    $candidate = if ($servicePath[1].Value) { $servicePath[1].Value } else { $servicePath[2].Value }
    if (Test-Path $candidate) { return (Resolve-Path $candidate).Path }
  }

  $uninstallRoots = @(
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
  )
  foreach ($entry in Get-ItemProperty $uninstallRoots -ErrorAction SilentlyContinue) {
    if ($entry.DisplayName -like 'RustDesk*') {
      if ($entry.InstallLocation) {
        $candidate = Join-Path $entry.InstallLocation 'rustdesk.exe'
        if (Test-Path $candidate) { return (Resolve-Path $candidate).Path }
      }
      if ($entry.DisplayIcon) {
        $candidate = ($entry.DisplayIcon -replace ',\d+$', '').Trim('"')
        if (Test-Path $candidate) { return (Resolve-Path $candidate).Path }
      }
    }
  }

  foreach ($candidate in @(
    "$env:ProgramFiles\RustDesk\rustdesk.exe",
    "${'${env:ProgramFiles(x86)}'}\RustDesk\rustdesk.exe",
    "$env:LOCALAPPDATA\Programs\RustDesk\rustdesk.exe"
  )) {
    if ($candidate -and (Test-Path $candidate)) { return (Resolve-Path $candidate).Path }
  }

  $command = Get-Command rustdesk.exe -ErrorAction SilentlyContinue
  if ($command) { return $command.Source }
  return $null
}

$RustDesk = Find-RustDesk
if (-not $RustDesk) {
  if (-not $InstallIfMissing) {
    throw 'RustDesk is not installed or could not be found. Enable automatic installation or install RustDesk first.'
  }

  $arch = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or $env:PROCESSOR_ARCHITEW6432 -eq 'ARM64') { 'aarch64' } else { 'x86_64' }
  $expectedHash = if ($arch -eq 'aarch64') { '${windowsHashes.aarch64}' } else { '${windowsHashes.x86_64}' }
  $msi = Join-Path $env:TEMP "rustdesk-$RustDeskVersion-$arch.msi"
  $download = "https://github.com/rustdesk/rustdesk/releases/download/$RustDeskVersion/rustdesk-$RustDeskVersion-$arch.msi"
  Invoke-WebRequest -UseBasicParsing -Uri $download -OutFile $msi
  $actualHash = (Get-FileHash -Algorithm SHA256 $msi).Hash.ToLowerInvariant()
  if ($actualHash -ne $expectedHash) { Remove-Item $msi -Force; throw 'RustDesk MSI checksum verification failed.' }
  $signature = Get-AuthenticodeSignature $msi
  if ($signature.Status -ne 'Valid') { Remove-Item $msi -Force; throw "RustDesk MSI signature verification failed: $($signature.Status)" }
  $process = Start-Process msiexec.exe -Wait -PassThru -ArgumentList @('/i', $msi, '/qn', 'CREATEDESKTOPSHORTCUTS=N', 'INSTALLPRINTER=N')
  Remove-Item $msi -Force -ErrorAction SilentlyContinue
  if ($process.ExitCode -notin @(0, 1641, 3010)) { throw "RustDesk MSI installation failed with exit code $($process.ExitCode)." }
  $RustDesk = Find-RustDesk
  if (-not $RustDesk) { throw 'RustDesk was installed but its executable could not be located.' }
}

if ($RustDeskConfig) {
  $configOutput = (& $RustDesk --config $RustDeskConfig 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or $configOutput -match 'required|failed|disabled') { throw "RustDesk configuration failed: $configOutput" }
}

$RustDeskId = ''
for ($attempt = 0; $attempt -lt 30 -and -not $RustDeskId; $attempt++) {
  $RustDeskId = ((& $RustDesk --get-id 2>$null | Out-String) -replace '[^0-9]', '').Trim()
  if (-not $RustDeskId) { Start-Sleep -Seconds 2 }
}
if ($RustDeskId -notmatch '^\d{6,12}$') { throw 'RustDesk did not return a valid device ID.' }

$recoveryDir = Join-Path $env:ProgramData 'rustdesk-book'
$recoveryPath = Join-Path $recoveryDir "enrollment-recovery-$RustDeskId.json"
New-Item -ItemType Directory -Force -Path $recoveryDir | Out-Null
& icacls.exe $recoveryDir /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'Could not secure the rustdesk-book recovery directory.' }

$recovery = $null
if (Test-Path $recoveryPath) {
  try { $recovery = Get-Content $recoveryPath -Raw | ConvertFrom-Json } catch { $recovery = $null }
}
$RustDeskPassword = $null
$ClaimToken = $null
if ($recovery -and $recovery.rustdeskId -eq $RustDeskId -and $recovery.password) {
  $RustDeskPassword = $recovery.password
  try {
    if ($recovery.claimToken -and $recovery.expiresAt -and [DateTimeOffset]::Parse($recovery.expiresAt) -gt [DateTimeOffset]::UtcNow) {
      $ClaimToken = $recovery.claimToken
    }
  } catch { $ClaimToken = $null }
}
if (-not $ClaimToken) {
  $claimPayload = @{
    rustdeskId = $RustDeskId
    alias = $env:COMPUTERNAME
    hostname = $env:COMPUTERNAME
    os = (Get-CimInstance Win32_OperatingSystem).Caption
    rustdeskVersion = (& $RustDesk --version 2>$null | Out-String).Trim()
  } | ConvertTo-Json
  $claim = Invoke-RestMethod -Method Post -Uri $ClaimUrl -Headers @{ Authorization = "Bearer $EnrollmentToken" } -ContentType 'application/json' -Body $claimPayload
  if ($claim.alreadyEnrolled) {
    Remove-Item $recoveryPath -Force -ErrorAction SilentlyContinue
    Write-Host "Device $env:COMPUTERNAME ($RustDeskId) is already present in rustdesk-book."
    exit 0
  }
  $ClaimToken = $claim.claimToken
  if (-not $RustDeskPassword) {
    $passwordBytes = [byte[]]::new(16)
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($passwordBytes) } finally { $rng.Dispose() }
    $RustDeskPassword = -join ($passwordBytes | ForEach-Object { $_.ToString('x2') })
  }
  @{ rustdeskId = $RustDeskId; password = $RustDeskPassword; claimToken = $ClaimToken; expiresAt = $claim.expiresAt } | ConvertTo-Json | Set-Content -Encoding UTF8 $recoveryPath
  & icacls.exe $recoveryPath /inheritance:r /grant:r '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
  if ($LASTEXITCODE -ne 0) { Remove-Item $recoveryPath -Force -ErrorAction SilentlyContinue; throw 'Could not secure the rustdesk-book recovery file.' }
}

$passwordOutput = (& $RustDesk --password $RustDeskPassword 2>&1 | Out-String)
if ($LASTEXITCODE -ne 0 -or $passwordOutput -match 'required|failed|disabled') { throw "Setting the RustDesk password failed: $passwordOutput" }

